CREATE TABLE IF NOT EXISTS "sv_citation_gap_snapshots" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "project_id" uuid NOT NULL REFERENCES "sv_projects"("id"), "cycle_id" uuid NOT NULL REFERENCES "sv_cycles"("id"), "configuration_lock_id" uuid NOT NULL REFERENCES "sv_configuration_locks"("id"), "topic_id" uuid, "source_domain" text NOT NULL, "source_urls" text[] DEFAULT '{}' NOT NULL, "owned_citation_count" integer NOT NULL, "competitor_citation_count" integer NOT NULL, "competitor_names" text[] DEFAULT '{}' NOT NULL, "engine_count" integer NOT NULL, "scenario_count" integer NOT NULL, "repeat_stability" numeric(6, 4), "first_seen" timestamptz, "last_seen" timestamptz, "gap_type" text, "priority_band" text NOT NULL, "formula_version" text NOT NULL, "evidence_run_ids" uuid[] DEFAULT '{}' NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "sv_citation_gap_cycle_source_unique" ON "sv_citation_gap_snapshots" ("cycle_id", "source_domain", "formula_version");
CREATE INDEX IF NOT EXISTS "sv_citation_gap_org_cycle_idx" ON "sv_citation_gap_snapshots" ("organization_id", "cycle_id"); CREATE INDEX IF NOT EXISTS "sv_citation_gap_project_idx" ON "sv_citation_gap_snapshots" ("project_id"); ALTER TABLE "sv_citation_gap_snapshots" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "sv_citation_gap_snapshots" ADD CONSTRAINT "sv_citation_gap_counts_non_negative" CHECK ("owned_citation_count" >= 0 AND "competitor_citation_count" >= 0 AND "engine_count" >= 1 AND "scenario_count" >= 1);
